import { createMiddleware } from '@tanstack/react-start';
import { requireSupabaseAuth } from './auth-middleware';
import { hasVerifiedMobileClaim, MOBILE_NOT_VERIFIED } from '@/lib/mobile-verification';

/**
 * Every merchant server function uses this instead of requireSupabaseAuth directly: the caller must be signed in AND
 * have a mobile number confirmed by OTP. Kept in its own file because auth-middleware.ts is generated by the platform.
 * The token's `phone` claim is only filled after the OTP was confirmed, and the token signature is verified first.
 */
export const requireVerifiedUser = createMiddleware({ type: 'function' })
  .middleware([requireSupabaseAuth])
  .server(async ({ next, context }) => {
    if (!hasVerifiedMobileClaim(context.claims)) throw new Error(MOBILE_NOT_VERIFIED);
    return next();
  });
